 b=p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox','--disable-dev-shm-usage']);c=b.new_context(viewport={'width':390,'height':844});page=c.new_page();errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.goto(base+'/games/backgammon');page.get_by_label('Backgammon match length',exact=True).select_option('1');page.get_by_role('button',name='Start Backgammon',exact=True).click();expect(page.get_by_role('region',name='Backgammon playing table')).to_be_visible();expect(page.locator('.bg-board-art [data-bg-point]')).to_have_count(24)
