 page.get_by_role('button',name='Help',exact=True).click();expect(page.get_by_role('dialog')).to_contain_text('Crawford');page.get_by_role('button',name='Back to game',exact=True).click();page.get_by_role('button',name='Sets',exact=True).click();expect(page.get_by_role('dialog')).to_contain_text('Clubhouse Walnut');page.get_by_role('button',name='Back to game',exact=True).click();page.reload();expect(page.get_by_role('region',name='Backgammon playing table')).to_be_visible();c.close()
 host=b.new_context(viewport={'width':390,'height':844});hp=host.new_page();hp.on('pageerror',lambda e:errors.append(str(e)));hp.goto(base+'/games/backgammon');hp.get_by_role('button',name='Real players',exact=True).click();hp.get_by_label('Backgammon variant',exact=True).select_option('nackgammon');hp.get_by_role('button',name='Create private table',exact=True).click();expect(hp.get_by_role('region',name='Backgammon multiplayer lobby')).to_be_visible();code=hp.evaluate('sessionStorage.getItem("clubhouse-backgammon:guest:room")');assert code
 peer=b.new_context(viewport={'width':390,'height':844});pp=peer.new_page();pp.goto(base+'/games/backgammon?room='+code);expect(pp.get_by_role('dialog')).to_be_visible();pp.get_by_label('Backgammon room code',exact=True).fill(code);pp.get_by_role('button',name='Join table',exact=True).click();pp.get_by_role('button',name='Ready to play',exact=True).click();expect(hp.get_by_role('button',name='Start match',exact=True)).to_be_enabled(timeout=8000);hp.get_by_role('button',name='Start match',exact=True).click();expect(hp.get_by_role('region',name='Backgammon playing table')).to_be_visible();expect(pp.get_by_role('region',name='Backgammon playing table')).to_be_visible(timeout=8000);expect(hp.locator('.bg-dice-line')).to_contain_text('Nackgammon');hp.screenshot(path=str(out/'online-nackgammon.png'));host.close();peer.close()
 shop=b.new_context(viewport={'width':390,'height':844});sp=shop.new_page();sp.goto(base+'/store?category=backgammon');expect(sp.get_by_role('heading',name='Backgammon',exact=True)).to_be_visible();expect(sp.locator('.bg-collection-grid article')).to_have_count(4);sp.get_by_role('button',name='Checker sets',exact=True).click();expect(sp.locator('.bg-collection-grid [data-bg-checkers]')).to_have_count(8);sp.screenshot(path=str(out/'checker-collections.png'));shop.close();assert not errors,errors;print(json.dumps({'realComputerGame':True,'smartMove':True,'onlineInvitesAndNackgammon':True,'phoneAndTabletFit':True,'themedCollections':True,'browserErrors':errors,'productionWrites':False}),flush=True);b.close()
